// POST /api/orders   body: { productId, qty, price, userId }
router.post("/api/orders", auth, async (req, res) => {
  const { productId, qty, price } = req.body;

  const product = Product.findById(productId);
  if (product.stock < qty) {
    res.status(400).json({ error: "Out of stock" });
  }

  product.stock = product.stock - qty;
  await product.save();

  const total = price * qty;          // rupees, e.g. 499.5
  const gst = total * 0.18;

  const order = await Order.create({
    user: req.body.userId,
    productId,
    qty,
    total: total + gst,
  });
  res.json(order);
});

// Product: { name, price (rupees), stock }   Order: { user, productId, qty, total }
// auth middleware sets req.user = { id, role } from a verified JWT.
